import sys

def insert_spaces(word):
    vowels = set('aeiou')
    n = len(word)
    result = []
    i = 0

    while i < n:
        if word[i] not in vowels:
            # Start of a consonant block
            start = i
            count = 1
            while i + 1 < n and word[i + 1] not in vowels:
                i += 1
                count += 1
            # Check for typo
            if count >= 3:
                unique_consonants = set(word[start:i+1])
                if len(unique_consonants) > 1:
                    result.append(word[start:start+2])
                    start += 2
                    while start <= i:
                        # Ensure no typo in remaining block
                        if i - start + 1 >= 3 and len(set(word[start:i+1])) > 1:
                            result.append(word[start:start+2])
                            start += 2
                        else:
                            result.append(word[start:i+1])
                            break
                else:
                    result.append(word[start:i+1])
            else:
                result.append(word[start:i+1])
        else:
            result.append(word[i])
        i += 1

    return ' '.join(result)

input = sys.stdin.read
word = input().strip()
print(insert_spaces(word))

